sys_script.script:
(function executeRule(current, previous /*null when async*/) {
    // FLEET-41: approval requests, reservation impact (D-02) and waitlist re-evaluation
    var fm = new FleetMaintenance();
    var state = current.getValue('maintenance_state');
    var isInsert = current.operation() == 'insert';

    if (current.getValue('approval') == 'requested' && (isInsert || current.approval.changes())) {
        fm.requestApproval(current);
    }
    if (state == 'SCHEDULED' && (isInsert || current.maintenance_state.changes() || current.scheduled_date.changes() ||
            current.expected_end_date.changes() || current.vehicle.changes())) {
        var out = fm.handleImpact(current);
        if (out.requeued.length) {
            gs.addInfoMessage('Reservations returned to the assignment queue: ' + out.requeued.join(', '));
        }
        if (out.active.length) {
            gs.addInfoMessage('Active trips overlap this maintenance (recall or check in): ' + out.active.join(', '));
        }
    }
    if (!isInsert && current.maintenance_state.changes() && (state == 'COMPLETED' || state == 'CANCELLED')) {
        if (state == 'CANCELLED') {
            fm._closeOtherApprovals(current.getUniqueValue(), '');
        }
        new FleetWaitlist().process(); // vehicle status is re-synced by "Maintenance - Sync vehicle status"
    }
})(current, previous);
